import React, { useState, useEffect } from 'react';

const Dashboard = () => {
  const [offset, setOffset] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e) => {
    const { innerWidth, innerHeight } = window;
    // حركة خفيفة للصورة بناءً على الماوس
    const x = (e.clientX / innerWidth - 0.5) * 30;
    const y = (e.clientY / innerHeight - 0.5) * 30;
    setOffset({ x, y });
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // دوال للتعامل مع الأزرار
  const handlePropertiesClick = () => {
    document.querySelector('button[title="العقارات"]')?.click();
  };

  const handleContactClick = () => {
    const fab = document.querySelector('.contact-fab');
    if (fab) fab.click();
  };

  const handleLoginClick = () => {
    const btn = document.querySelector('#client-login-button');
    if (btn) btn.click();
  };

  return (
    <div className="container-fluid p-0 overflow-hidden" style={{ minHeight: '80vh' }}>
      <div className="row g-0 align-items-center" style={{ minHeight: '80vh' }}>
        
        {/* القسم النصي */}
        <div className="col-lg-6 p-5 fade-in" style={{ zIndex: 2 }}>
          <div className="p-lg-5">
            <h1 className="display-3 fw-bold mb-4" style={{ background: 'linear-gradient(45deg, #667eea, #764ba2)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
              مستقبل العقارات <br/> بين يديك
            </h1>
            <p className="lead text-muted mb-5" style={{ lineHeight: '1.8' }}>
              منصة <strong>سمسار برو</strong> هي الحل الأمثل لإدارة وتسويق العقارات بذكاء. 
              نجمع بين التكنولوجيا الحديثة وسهولة الاستخدام لنوفر لك تجربة فريدة.
            </p>
            
            <div className="d-flex gap-3 flex-wrap">
              <button className="btn btn-primary btn-lg px-4 rounded-pill shadow-lg" onClick={handlePropertiesClick}>
                تصفح العقارات
              </button>
              <button className="btn btn-outline-secondary btn-lg px-4 rounded-pill" onClick={handleContactClick}>
                تواصل معنا
              </button>
              <button className="btn btn-success btn-lg px-4 rounded-pill shadow-lg" onClick={handleLoginClick}>
                سجل دخولك الآن
              </button>
            </div>

            <div className="mt-5 pt-4 border-top">
              <div className="row text-center">
                <div className="col">
                  <h3 className="fw-bold text-primary">+500</h3>
                  <small className="text-muted">عقار متاح</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">+100</h3>
                  <small className="text-muted">عميل سعيد</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">24/7</h3>
                  <small className="text-muted">دعم فني</small>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* القسم التفاعلي 3D */}
        <div className="col-lg-6 d-flex justify-content-center align-items-center" style={{ height: '60vh', perspective: '1000px' }}>
          <div 
            className="house-3d"
            style={{
              position: 'relative',
              width: '200px',
              height: '200px',
              transformStyle: 'preserve-3d',
              transform: `rotateX(${rotation.x}deg) rotateY(${rotation.y}deg)`,
              transition: 'transform 0.1s ease-out'
            }}
          > 
            {/* Walls */}
            <div className="face front" style={{...faceStyle, transform: 'translateZ(100px)', background: '#f0e4d7' }}></div>
            <div className="face back" style={{...faceStyle, transform: 'rotateY(180deg) translateZ(100px)', background: '#f0e4d7' }}></div>
            <div className="face right" style={{...faceStyle, transform: 'rotateY(90deg) translateZ(100px)', background: '#e0d4c7' }}></div>
            <div className="face left" style={{...faceStyle, transform: 'rotateY(-90deg) translateZ(100px)', background: '#e0d4c7' }}></div>
            <div className="face bottom" style={{...faceStyle, width: '200px', height: '200px', background: '#8c7853', transform: 'rotateX(-90deg) translateZ(100px)'}}></div>

            {/* Roof */}
            <div className="roof-side" style={{...roofStyle, transform: 'rotateY(0deg) rotateX(45deg) translate3d(0, -70px, 70px)'}}></div>
            <div className="roof-side" style={{...roofStyle, transform: 'rotateY(180deg) rotateX(45deg) translate3d(0, -70px, 70px)'}}></div>
            <div className="roof-side" style={{...roofStyle, transform: 'rotateY(90deg) rotateX(45deg) translate3d(0, -70px, 70px)'}}></div>
            <div className="roof-side" style={{...roofStyle, transform: 'rotateY(-90deg) rotateX(45deg) translate3d(0, -70px, 70px)'}}></div>

            {/* Door */}
            <div style={{...faceStyle, width: '50px', height: '80px', background: '#8b5a2b', transform: 'translateZ(101px) translateY(60px) translateX(75px)'}}></div>
            {/* Window */}
            <div style={{...faceStyle, width: '50px', height: '50px', background: '#87ceeb', border: '5px solid white', transform: 'rotateY(90deg) translateZ(101px) translateY(15px)'}}></div>
          </div>
        </div>
      </div>

      <style>{`
        .face {
          position: absolute;
          width: 200px;
          height: 200px;
          background: rgba(255, 255, 255, 0.9);
          border: 2px solid #eee;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 4rem;
          box-shadow: inset 0 0 20px rgba(0,0,0,0.1);
          backface-visibility: visible;
        }
        .house-3d {
          animation: float 6s ease-in-out infinite;
        }
        @keyframes float {
          0%, 100% { transform: rotateX(-10deg) rotateY(30deg) translateY(0); }
          50% { transform: rotateX(-10deg) rotateY(30deg) translateY(-20px); }
        }
      `}</style>
    </div>
  );
};

const faceStyle = {
  position: 'absolute',
  width: '200px',
  height: '200px',
  background: 'linear-gradient(to bottom, #fff, #f0f0f0)',
  border: '1px solid #ccc',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  fontSize: '50px',
  userSelect: 'none'
};

const roofStyle = {
  position: 'absolute',
  width: '141.4px',
  height: '141.4px',
  background: '#c0392b',
  border: '1px solid #a03024',
  top: '29.5px',
  left: '29.5px'
};

export default Dashboard;
